 function doDodge(){if(!started||dodge>0)return;dodge=.35;player.position.add(new THREE.Vector3(Math.sin(yaw),0,Math.cos(yaw)).multiplyScalar(-1.8));toast('PHANTOM STEP')}
 function spawnSlash(power){const points=[];let origin=player.position.clone().add(new THREE.Vector3(0,1.15,0));let angle=yaw;for(let i=0;i<18;i++){let t=i/17;let a=angle-.9+t*1.8;points.push(new THREE.Vector3(origin.x+Math.sin(a)*(.65+power*.22),origin.y+Math.sin(t*Math.PI)*(.5+power*.2),origin.z-Math.cos(a)*(.65+power*.22)))}let geo=new THREE.BufferGeometry().setFromPoints(points);let line=new THREE.Line(geo,new THREE.LineBasicMaterial({color:power>1?0xffe6a3:0xff7ca9,transparent:true,opacity:.9}));scene.add(line);hitEffects.push({obj:line,t:.22,max:.22});
 for(let i=0;i<12+power*7;i++){let m=new THREE.Mesh(new THREE.SphereGeometry(.035+Math.random()*.045,6,6),i%2?pink:gold);m.position.copy(origin);scene.add(m);particles.push({m,v:new THREE.Vector3((Math.random()-.5)*5,Math.random()*4,(Math.random()-.5)*5),life:.45+Math.random()*.25})}}
 function hitTargets(power,range,arc,damage){let hit=false;let forward=new THREE.Vector3(Math.sin(yaw),0,-Math.cos(yaw));let selected=locked&&lockDummy?lockDummy:closestDummy();for(const d of dummies){if(d.hp<=0)continue;let delta=d.root.position.clone().sub(player.position);let dist=delta.length();if(dist>range)continue;delta.y=0;let dot=forward.dot(delta.normalize());if(d===selected||dot>Math.cos(arc)){d.hp=Math.max(0,d.hp-damage);d.flash=.18;totalDamage+=damage;energy=Math.min(100,energy+damage*.55);combo++;comboTimer=2.3;hit=true;d.body.scale.set(1.05,.94,1.05);setTimeout(()=>d.body.scale.set(1,1,1),90);if(d.hp===0){toast('CONSTRUCT DISABLED · '+damage+' DMG');d.root.userData.respawn=4.5}else if(hit){$('hitflash').classList.remove('on');void $('hitflash').offsetWidth;$('hitflash').classList.add('on')}}}if(hit){$('damageNum').textContent=String(totalDamage).padStart(3,'0');$('comboNum').textContent=combo;$('combo').classList.add('on')}return hit}
