+function attack(kind){if(!started||attackTimer>0||dodge>0)return;attackKind=kind;attackTimer=kind==='heavy'?.65:.42;attackStep=kind==='heavy'?0:(attackStep%3)+1;let dmg=kind==='heavy'?28:([10,13,19][attackStep-1]);if(kind==='heavy')toast('HEAVY BREAK');else if(attackStep===3)toast('FINISHER · STARFALL CUT');spawnSlash(kind==='heavy'?2:attackStep);let hit=hitTargets(kind==='heavy'?1.5:1.35,4.4,kind==='heavy'?1.5:1.25,dmg);if(!hit&&kind==='light'){} }
 function skill(){if(!started||skillCd>0)return;skillCd=7;energy=Math.min(100,energy+8);attackKind='skill';attackTimer=.72;toast('MOONLIT CROSS · 32 DMG');spawnSlash(2.5);hitTargets(2,5.4,2.2,32)}
 function burst(){if(!started||burstCd>0)return;if(energy<100){toast('RESONANCE NOT FULL');return}energy=0;burstCd=7;attackKind='burst';attackTimer=1.05;toast('✦ &nbsp; STARFALL: CELESTIAL SEVER');spawnSlash(3);hitTargets(3,7,Math.PI,70);for(let i=0;i<3;i++)setTimeout(()=>spawnSlash(2.2),i*120)}
 function updateHUD(){ $('hpBar').style.width=playerHP+'%';$('hpText').textContent=Math.round(playerHP)+' / 100';$('energyBar').style.width=energy+'%';$('energyText').textContent=Math.floor(energy)+' / 100';$('skillQ').classList.toggle('cool',skillCd>0);$('skillR').classList.toggle('cool',energy<100||burstCd>0);$('skillF').classList.toggle('ready',attackTimer<=0);$('skillQ').querySelector('small').textContent=skillCd>0?skillCd.toFixed(1)+'S':'SKILL';$('skillR').querySelector('small').textContent=energy>=100?'READY':'BURST';}
 function update(dt){let t=clock.elapsedTime;toastTimer=Math.max(0,toastTimer-dt);if(toastTimer<=0)$('toast').classList.remove('show');attackTimer=Math.max(0,attackTimer-dt);skillCd=Math.max(0,skillCd-dt);burstCd=Math.max(0,burstCd-dt);dodge=Math.max(0,dodge-dt);if(comboTimer>0){comboTimer-=dt;if(comboTimer<=0){combo=0;$('combo').classList.remove('on')}}
